-- 2026-10-20: plain-English hover help for each Risk Dial gauge (shown on the rank chip in the Dashboard Risk Dial).
-- Bulleted text: first line = what it means, then 'Fires when' and 'Why it matters'. Edit here or in ref_risk_gauge.help.

UPDATE ref_risk_gauge SET help = E'The S&P 500 is near the top of its expected range, so there is less room to rise and more room to fall.\n- Fires when: SPX is in the top 15% of its Hedgeye risk range (85% or more of the way from LRR to TRR).\n- Why it matters: Buying near the top of the range has historically paid less and risked more.' WHERE gauge_key = 'spx_top_range';
UPDATE ref_risk_gauge SET help = E'The S&P 500 has dropped to the bottom of its expected range.\n- Fires when: SPX is in the bottom 15% of its risk range (15% or less of the way from LRR to TRR).\n- Why it matters: A break below the range often means the selling is still going, so it counts as risk.' WHERE gauge_key = 'spx_bottom_range';
UPDATE ref_risk_gauge SET help = E'Stocks jumped but the VIX (fear gauge) went up too. They normally move in opposite directions.\n- Fires when: SPX is up 1.5% or more today while the VIX is also up.\n- Why it matters: When fear rises into a rally, the rally is not trusted and a reversal is more likely.' WHERE gauge_key = 'vix_spx_divergence';
UPDATE ref_risk_gauge SET help = E'The VIX (expected S&P 500 swings) is high.\n- Fires when: VIX is above 30.\n- Why it matters: High volatility means bigger price swings and forced selling, so positions should be smaller.' WHERE gauge_key = 'vix_elevated';
UPDATE ref_risk_gauge SET help = E'The Nasdaq 100 volatility index (VXN) is high.\n- Fires when: VXN is above 32.\n- Why it matters: Tech and growth stocks are being priced for bigger swings, so risk is higher.' WHERE gauge_key = 'vxn_elevated';
UPDATE ref_risk_gauge SET help = E'The Russell 2000 volatility index (RVX) is high.\n- Fires when: RVX is above 40.\n- Why it matters: Small caps are the most sensitive to stress, so this often warns early.' WHERE gauge_key = 'rvx_elevated';
UPDATE ref_risk_gauge SET help = E'The MOVE index (expected swings in Treasury bonds) is high.\n- Fires when: MOVE is above 120.\n- Why it matters: Bond turmoil spreads to stocks through borrowing costs, so it is a heavy warning.' WHERE gauge_key = 'move_elevated';
UPDATE ref_risk_gauge SET help = E'The cost of borrowing for risky companies is rising, a sign that investors are getting nervous.\n- Fires when: Any one of: the high-yield spread widened 25 bp or more in 10 days, 40 bp or more in 20 days, or the junk-bond ETF (HYG) is in the bottom 15% of its range.\n- Why it matters: Credit often weakens before stocks do.' WHERE gauge_key = 'credit_stress';
UPDATE ref_risk_gauge SET help = E'Safer (investment-grade) companies are paying more to borrow.\n- Fires when: The IG credit spread widened 10 bp or more in 10 trading days.\n- Why it matters: Even the safest borrowers getting charged more is an early stress sign.' WHERE gauge_key = 'ig_spread_widening';
UPDATE ref_risk_gauge SET help = E'The weakest investment-grade companies (BBB) are paying more to borrow.\n- Fires when: The BBB spread widened 15 bp or more in 20 trading days.\n- Why it matters: BBB is the first place stress shows beyond junk bonds, so it warns early.' WHERE gauge_key = 'bbb_spread_widening';
UPDATE ref_risk_gauge SET help = E'Credit is flashing a warning that stocks have not reacted to yet.\n- Fires when: The high-yield spread widened 25 bp or more in 10 days while the S&P 500 is still in the top 30% of its range.\n- Why it matters: Credit often leads stocks, so this is the setup before a drop.' WHERE gauge_key = 'credit_equity_divergence';
UPDATE ref_risk_gauge SET help = E'The 10-year Treasury yield is at a level you are watching or near the top of its range.\n- Fires when: The 10Y yield is within about 0.1 point of a watched level (4.0%, 4.5% or 5.0%), or in the top 15% of its risk range.\n- Why it matters: Fast or high yields raise borrowing costs and pressure stock prices.' WHERE gauge_key = 'yield_level_watch';
UPDATE ref_risk_gauge SET help = E'The gap between 10-year and 2-year yields (2s10s) is falling quickly toward inversion.\n- Fires when: The 2s10s spread fell 15 bp or more in 5 trading days.\n- Why it matters: A curve that inverts has historically come before recessions.' WHERE gauge_key = 'curve_inverting';
UPDATE ref_risk_gauge SET help = E'Short-term Treasury yields are higher than long-term ones (3-month vs 10-year).\n- Fires when: The 10-year yield minus the 3-month yield is below zero.\n- Why it matters: This is a widely watched recession warning, though it can take months to play out.' WHERE gauge_key = '3m10y_inverted';
UPDATE ref_risk_gauge SET help = E'A recession signal built from the unemployment rate.\n- Fires when: The Sahm Rule reading is 0.50 points or more.\n- Why it matters: It has historically signaled recessions early, so it carries the top weight.' WHERE gauge_key = 'sahm_rule';
UPDATE ref_risk_gauge SET help = E'Financial conditions (credit, markets, borrowing) are tighter than average.\n- Fires when: The Chicago Fed NFCI is above 0.\n- Why it matters: Tight conditions slow the economy and weigh on risk assets.' WHERE gauge_key = 'nfci_tightening';
UPDATE ref_risk_gauge SET help = E'More people are filing for unemployment benefits.\n- Fires when: The 4-week average of initial jobless claims is 10% or more above its level 8 weeks ago.\n- Why it matters: Layoffs rising is an early sign the job market is weakening.' WHERE gauge_key = 'claims_rising';
UPDATE ref_risk_gauge SET help = E'The US dollar is near the top of its expected range.\n- Fires when: The dollar index (DXY) is in the top 15% of its risk range.\n- Why it matters: A strong dollar squeezes global liquidity, multinational profits and commodities.' WHERE gauge_key = 'dollar_strong';
UPDATE ref_risk_gauge SET help = E'The yen is jumping, which can force investors to sell stocks to repay cheap yen loans.\n- Fires when: Yen futures (/6J) are up 1.0% or more today.\n- Why it matters: A sharp yen jump can force leveraged traders to unwind positions across markets.' WHERE gauge_key = 'jpy_carry_unwind';
UPDATE ref_risk_gauge SET help = E'Factory activity is shrinking badly.\n- Fires when: The latest ISM Manufacturing reading is below 45 (50 is the line between growth and shrinking).\n- Why it matters: Weak factory orders often lead profits and stocks lower.' WHERE gauge_key = 'ism_mfg_contraction';
UPDATE ref_risk_gauge SET help = E'Service-sector activity is shrinking badly.\n- Fires when: The latest ISM Services reading is below 45.\n- Why it matters: Services are most of the economy, so a weak reading is a real growth warning.' WHERE gauge_key = 'ism_svcs_contraction';
UPDATE ref_risk_gauge SET help = E'Oil is making an extreme move, either way, or oil volatility is high.\n- Fires when: WTI is in the top or bottom 15% of its risk range, or the oil volatility index (OVX) is above 50.\n- Why it matters: Big oil moves hit inflation and growth, and often come with market stress.' WHERE gauge_key = 'oil_shock';
UPDATE ref_risk_gauge SET help = E'Options are no longer expensive compared with how much the market is actually moving.\n- Fires when: The VIX minus 1-month realized volatility is zero or less.\n- Why it matters: When realized swings catch up to what options charge, the calm is fading.' WHERE gauge_key = 'vrp_gone';
UPDATE ref_risk_gauge SET help = E'Very short-term options (9-day) are not priced above recent real swings.\n- Fires when: VIX9D minus the 10-day realized volatility is zero or less.\n- Why it matters: The market is not paying extra for near-term protection, so a surprise move is more likely.' WHERE gauge_key = 'short_vol_disc';
UPDATE ref_risk_gauge SET help = E'Short-term options are very cheap, which signals complacency.\n- Fires when: VIX9D is 12 or below (its normal range is about 10 to 30).\n- Why it matters: Cheap short-term fear often comes right before volatility rises.' WHERE gauge_key = 'short_vol_low';
UPDATE ref_risk_gauge SET help = E'Rule-based volatility funds are likely selling stocks.\n- Fires when: SPX 1-month realized volatility is above 3-month and higher than 5 sessions ago.\n- Why it matters: These funds cut stock holdings when volatility rises, which can push prices down.' WHERE gauge_key = 'vol_funds_selling';
UPDATE ref_risk_gauge SET help = E'Options dealers make market moves bigger.\n- Fires when: Dealer Gamma Throttle is below 0, or SPX is below the GEX flip line (the throttle is a morning snapshot; the flip line is the live test).\n- Why it matters: Dealers buy rallies and sell drops, so swings are larger in both directions.' WHERE gauge_key = 'gamma_negative';
UPDATE ref_risk_gauge SET help = E'Options dealers are only a weak calming force.\n- Fires when: Dealer Gamma Throttle is between 0 and 2.\n- Why it matters: Dealer buying on dips is fading, so a drop can run further than usual.' WHERE gauge_key = 'gamma_neutral';
UPDATE ref_risk_gauge SET help = E'The dollar and gold usually move opposite each other. That link is weakening.\n- Fires when: The 30-day dollar to gold correlation is above -0.3.\n- Why it matters: A broken pattern means markets are being driven by something unusual.' WHERE gauge_key = 'usd_gold_decorrelation';
UPDATE ref_risk_gauge SET help = E'The dollar and the S&P 500 usually move opposite each other. That link is weakening.\n- Fires when: The 30-day dollar to SPX correlation is above -0.3.\n- Why it matters: A broken pattern can mean stress or a regime change.' WHERE gauge_key = 'usd_spx_decorrelation';
UPDATE ref_risk_gauge SET help = E'Fewer stocks are taking part in the market.\n- Fires when: Fewer than 40% of stocks are above their 50-day average and that share fell over the last 5 days.\n- Why it matters: A rally held up by a few stocks is fragile.' WHERE gauge_key = 'breadth_deteriorating';
UPDATE ref_risk_gauge SET help = E'Gold volatility is high.\n- Fires when: The gold volatility index (GVZ) is above 32.\n- Why it matters: Even the safe-haven asset is swinging hard, which signals broad uncertainty.' WHERE gauge_key = 'gold_vol_elevated';
UPDATE ref_risk_gauge SET help = E'In Quad 2, rising inflation, oil and yields together can hurt stocks.\n- Fires when: The dominant quad is 2, the 10Y and 30Y yield trends are bullish, WTI is bullish, and the Hedgeye CPI nowcast is rising.\n- Why it matters: Quad 2 is usually good for stocks, but this combination can force the Fed to turn hawkish.' WHERE gauge_key = 'quad2_overheat';
UPDATE ref_risk_gauge SET help = E'Market signals say growth is slowing even though the Quad expects growth to rise. (Inactive for now.)\n- Fires when: The Quad is 1 or 2 and the market growth meter is at or below -20 for 2 days.\n- Why it matters: It is an early sign the Quad is about to change.' WHERE gauge_key = 'quad_growth_break';
UPDATE ref_risk_gauge SET help = E'The VIX is in its in-between zone. (Inactive: warnings removed.)\n- Fires when: VIX is between 19 and 30.\n- Why it matters: A middle zone is not calm and not stressed.' WHERE gauge_key = 'vix_chop';
UPDATE ref_risk_gauge SET help = E'The VXN is in its in-between zone. (Inactive: warnings removed.)\n- Fires when: VXN is between 22 and 32.\n- Why it matters: A middle zone is not calm and not stressed.' WHERE gauge_key = 'vxn_chop';
UPDATE ref_risk_gauge SET help = E'The RVX is in its in-between zone. (Inactive: warnings removed.)\n- Fires when: RVX is between 22 and 40.\n- Why it matters: A middle zone is not calm and not stressed.' WHERE gauge_key = 'rvx_chop';
UPDATE ref_risk_gauge SET help = E'The MOVE index is in its in-between zone. (Inactive: warnings removed.)\n- Fires when: MOVE is between 100 and 120.\n- Why it matters: A middle zone is not calm and not stressed.' WHERE gauge_key = 'move_chop';
UPDATE ref_risk_gauge SET help = E'More trading volume is in falling stocks than in rising stocks. (Inactive until the volume feed is confirmed.)\n- Fires when: Up-volume share of total volume is below 35%.\n- Why it matters: Selling pressure under the surface warns before the index falls.' WHERE gauge_key = 'volume_breadth_weak';
UPDATE ref_risk_gauge SET help = E'Hedgeye''s own lists are getting smaller. (Inactive.)\n- Fires when: 3 or more of the 4 lists (RR, ETF Pro, PS, SSS) are down more than 25% versus about 4 weeks ago.\n- Why it matters: Hedgeye cutting its own bullish lists is a de-risking signal.' WHERE gauge_key = 'lists_derisking';
UPDATE ref_risk_gauge SET help = E'Hedgeye''s ETF Pro list has no more longs than shorts. (Inactive.)\n- Fires when: ETF Pro longs minus shorts is zero or less.\n- Why it matters: The list is no longer leaning bullish.' WHERE gauge_key = 'etf_net_short';
UPDATE ref_risk_gauge SET help = E'Hedgeye''s Signal Strength Stocks long list is collapsing. (Inactive.)\n- Fires when: SSS rows are down 40% or more from their own 4-week high.\n- Why it matters: Fewer strong stocks means weaker market support.' WHERE gauge_key = 'sss_book_collapse';
UPDATE ref_risk_gauge SET help = E'Many Risk Range outlooks flipped at once. (Inactive.)\n- Fires when: 9 or more RR flips versus the prior day, within the last 3 sessions.\n- Why it matters: A mass flip means Hedgeye''s market read is changing fast.' WHERE gauge_key = 'rr_flip_day';
UPDATE ref_risk_gauge SET help = E'Hedgeye''s lists disagree with the Quad playbook. (Inactive.)\n- Fires when: 4 or more themes conflict with the Quad playbook.\n- Why it matters: Mixed signals mean lower confidence in the current plan.' WHERE gauge_key = 'lists_quad_conflict';
UPDATE ref_risk_gauge SET help = E'You hold a lot of money in themes Hedgeye is bearish on. (Inactive.)\n- Fires when: 15% or more of your risk dollars sit in bear-stance themes.\n- Why it matters: You are positioned against the lists.' WHERE gauge_key = 'exposed_bear_themes';
